/* COMEDY COMMANDOS · J-STYLES: THE CHAIRMAN · RUC WRESTLING EXPANSION
   Standalone guest and owner compatible. No creator-only Godkey privileges included. */
(function(){
'use strict';
if (!window.__CC_WEAPON_TEST__ || !Array.isArray(roster)) {
 console.error('J-Styles needs the Weapon Arts game engine.');
 return;
}
if(byId.jstyles) return;
const assets=["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
for(let i=0;i<4;i++){
 const key='jstyles_'+i;
 EMBEDDED_ASSETS[key]=assets[i];
 const img=new Image();img.decoding='async';img.src=assets[i];sprites[key]=img;
}
sheets.push('jstyles');
const j={id:'jstyles',name:'J-Styles',faction:'RUC',role:'THE CHAIRMAN · Hardcore Wrestler',color:'#ff445b',
 special:'SOUTHSIDE CLINCH',finisher:'CHAIRMAN’S VERDICT',line:'J-STYLES JUST TOOK OVER THE RING!'};
roster.push(j);byId[j.id]=j;
SUPER_ART.jstyles={symbol:'♜',theme:'chair',caption:'J-STYLES • THE CHAIRMAN',trait:'guardbreak',reach:95,bonus:6};
FIGHT_STYLES.jstyles={name:'Hardcore Wrestling & Ringside Brawling',speed:.97,jump:.90,reach:1.19,power:1.18,
 route:['punch','lowkick','highkick'],combo:'Southside Slam Chain',effect:'guardbreak',bonus:8,
 weapon:'Steel Folding Chair',powerName:'Chairman’s Verdict',stanceName:'Hardcore Clinch',
 archetype:'grappler',weaponType:'chair',tech:'grab'};
// PROFILES is scoped to Weapon Arts, but its read-only test object exposes the same mutable dictionary.
const profile=window.__CC_WEAPON_TEST__.profiles;
profile.jstyles={weapon:'Steel Folding Chair',power:'Chairman’s Verdict',stance:'Hardcore Clinch',
 archetype:'grappler',tech:'grab',prop:'chair',reach:1.35,damage:1.17,combo:'A → D → C',pose:'punch'};

const oldAction=action;
action=function(side,kind){
 const f=game?.teams?.[side],isJ=f&&activeWho(f)?.id==='jstyles';
 if(!isJ) return oldAction(side,kind);
 const before=f.attack;
 oldAction(side,kind);
 if(!f.attack || f.attack===before)return;
 const a=f.attack;
 if(kind==='punch'){
   // Tight, rapid grappler jab, not another generic lunging kick.
   a.damage*=1.12;a.reach=Math.min(a.reach,151);a.duration*=.9;
 }else if(kind==='lowkick'){
   // Knee-check sets up a close-range slam and short stun.
   a.damage*=.98;a.reach=Math.min(a.reach,170);a.jstylesKnee=true;
 }else if(kind==='highkick'){
   // In J-Styles' hands this is an overhead shoulder-and-chair launcher.
   a.damage*=1.22;a.reach=Math.max(a.reach,178);a.jstylesLauncher=true;
 }else if(kind==='special'){
   // Wrestler-exclusive running clinch, opponent throw and chair follow-through.
   a.jstylesClinch=true;a.technique='grab';a.reach=Math.max(a.reach,273);
   a.damage*=1.26;a.duration*=1.03;a.power*=1.22;
   const e=enemyOf(f);const toward=Math.sign(e.x-f.x)||f.face;
   f.x=Math.max(95,Math.min(W-95,f.x+toward*Math.min(90,Math.max(0,Math.abs(e.x-f.x)-115))));
   announce('J-STYLES • SOUTHSIDE CLINCH!',.7);
 }else if(kind==='finish'){
   a.jstylesFinale=true;a.technique='grab';a.damage*=1.18;a.reach=Math.max(a.reach,365);
   a.power*=1.2;cameraMode='low';cameraPulse=Math.max(cameraPulse,1.7);
   announce('THE CHAIRMAN’S VERDICT!',1.05);
 }
};
const oldRegisterHit=registerHit;
registerHit=function(f,e,a){
 const targetBefore=e.hp[e.active];
 oldRegisterHit(f,e,a);
 if(activeWho(f)?.id!=='jstyles'||!a.didHit||e.hp[e.active]>=targetBefore)return;
 if(a.jstylesKnee){e.stun=Math.max(e.stun,.25);e.vy=Math.min(e.vy,-95);}
 if(a.jstylesLauncher){e.vy=Math.min(e.vy,-245);e.stun=Math.max(e.stun,.32);}
 if(a.jstylesClinch){
   e.vy=Math.min(e.vy,-350);e.stun=Math.max(e.stun,.8);
   e.x=Math.max(95,Math.min(W-95,f.x+f.face*118));
   spawnRing(e.x,FLOOR+e.y-118,'#ff586e',70);spawnBurst(e.x,FLOOR+e.y-120,'#ffd05d',25);
   shake=Math.max(shake,12);cameraPulse=Math.max(cameraPulse,1);
 }
 if(a.jstylesFinale){
   e.vy=Math.min(e.vy,-420);e.stun=Math.max(e.stun,1.3);
   spawnRing(e.x,FLOOR+e.y-135,'#ff3658',110);spawnBurst(e.x,FLOOR+e.y-145,'#ffe9b5',50);
   shake=Math.max(shake,21);cameraPulse=Math.max(cameraPulse,2);
 }
};
const oldDrawFighter=drawFighter;
drawFighter=function(f,t){
 oldDrawFighter(f,t);
 if(activeWho(f)?.id!=='jstyles'||!f.attack)return;
 const a=f.attack;
 if(!a.jstylesClinch&&!a.jstylesFinale&&!a.jstylesLauncher)return;
 const phase=Math.min(1,a.t/Math.max(.01,a.duration));
 ctx.save();ctx.translate(f.x+f.face*80,FLOOR+f.y-183);
 ctx.scale(f.face,1);ctx.globalAlpha=.7*Math.sin(Math.PI*phase);
 ctx.strokeStyle='#ff445b';ctx.shadowColor='#ff445b';ctx.shadowBlur=23;ctx.lineWidth=6;
 ctx.rotate(-.65+phase*1.35);
 // Recognizable folding-chair silhouette with animated sweep arc, not a sword.
 ctx.strokeRect(-30,-54,61,72);ctx.beginPath();ctx.moveTo(-27,-26);ctx.lineTo(28,-26);
 ctx.moveTo(-26,18);ctx.lineTo(-43,62);ctx.moveTo(29,18);ctx.lineTo(45,62);ctx.stroke();
 ctx.restore();
};
const oldShowStyles=showStyles;
showStyles=function(){oldShowStyles();const head=document.querySelector('.panel h2');if(head)head.textContent=roster.length+' FIGHTER WEAPON & POWER DOSSIERS';
 const card=[...document.querySelectorAll('.weapon-card')].find(x=>x.querySelector('h3')?.textContent==='J-Styles');
 if(card){const para=card.querySelector('p');if(para)para.innerHTML+='<br>🤼 SIGNATURES: Southside Clinch · Chair Check · Stunner-style Slam · Chairman’s Verdict';}
};
// In-match context action for grapples. Owner Godkey and other roster controls are unchanged.
const bar=document.querySelector('.subactions');let grappleButton=null;
if(bar){
 grappleButton=document.createElement('button');grappleButton.type='button';grappleButton.className='stance-btn';
 grappleButton.textContent='🤼 CHAIR CLINCH';grappleButton.setAttribute('aria-label','J Styles wrestler grapple special');
 grappleButton.style.display='none';
 grappleButton.addEventListener('pointerdown',e=>{e.preventDefault();initAudio();action(0,'special');});
 bar.appendChild(grappleButton);
}
const oldUpdateFight=updateFight;
updateFight=function(dt){const r=oldUpdateFight(dt);
 if(grappleButton){const f=game?.teams?.[0];grappleButton.style.display=state==='fight'&&f&&activeWho(f).id==='jstyles'?'inline-block':'none';}
 return r;};
window.addEventListener('keydown',e=>{if(e.code==='KeyG'&&!e.repeat&&state==='fight'&&game?.teams?.[0]&&activeWho(game.teams[0]).id==='jstyles'){
 e.preventDefault();initAudio();action(0,'special');}});
window.__CC_JSTYLES_TEST__={version:'J-Styles Wrestler v1',fighter:j,getStyles:()=>FIGHT_STYLES.jstyles,
 getProfile:()=>profile.jstyles,getCurrent:()=>game,action};
showMenu();
})();